using System.Text.Json;
using System.Text.Json.Nodes;
using System.Windows;
using KarimEldamatyWindows;
var checks=new List<string>();var failures=new List<string>();
void Test(string name,Action action){try{action();checks.Add(name);}catch(Exception ex){failures.Add(name+": "+ex.Message);}}
void Assert(bool condition,string message="Assertion failed"){if(!condition)throw new Exception(message);}
void Near(double a,double b,double error=1e-8)=>Assert(Math.Abs(a-b)<error,$"Expected {b}, got {a}");
void Reject(Action action){try{action();}catch(InvalidDataException){return;}catch(JsonException){return;}throw new Exception("Invalid input was accepted");}
var fixture=Path.Combine(AppContext.BaseDirectory,"swift-fixture.engboard");if(!File.Exists(fixture))fixture=Path.Combine(Environment.CurrentDirectory,"swift-fixture.engboard");
Test("Swift JSONEncoder UUID/date/Data/pressure interoperability",()=>{var b=BoardCodec.Read(fixture);Assert(b.Id==Guid.Parse("EE2C8255-95C7-419E-8DBF-EE64487C63D3"));Near(b.Created,0);Near(b.Modified,23456.125);Near(b.Elements[0].Points[0].RawPressure!.Value,.7);Assert(b.Elements[0].ImageData!.SequenceEqual(new byte[]{0,1,2,255}));Assert(b.NotionURL=="https://example.test/notion");var root=JsonNode.Parse(BoardCodec.Serialize(b))!.AsObject();Assert(root.ContainsKey("notionURL")&&root.ContainsKey("whiteboardURL")&&root.ContainsKey("pointsPerMM"));Near(root["created"]!.GetValue<double>(),0);Assert(!root.ContainsKey("bounds"));});
Test("Unknown fields survive every model level",()=>{var root=JsonNode.Parse(File.ReadAllText(fixture))!;root["futureBoard"] = JsonNode.Parse("{\"revision\":42}");var e=root["elements"]![0]!;e["futureElement"]=true;e["points"]![0]!["futureSample"]="raw";e["color"]!["futureColor"]=.7;e["brushSettings"]!["futureBrush"]=new JsonArray(1,2,3);var b=BoardCodec.Deserialize(root.ToJsonString());var again=JsonNode.Parse(BoardCodec.Serialize(BoardCodec.Clone(b)))!;Assert(again["futureBoard"]!["revision"]!.GetValue<int>()==42);Assert(again["elements"]![0]!["futureElement"]!.GetValue<bool>());Assert(again["elements"]![0]!["points"]![0]!["futureSample"]!.GetValue<string>()=="raw");Assert(again["elements"]![0]!["color"]!["futureColor"]!.GetValue<double>()==.7);Assert(again["elements"]![0]!["brushSettings"]!["futureBrush"]!.AsArray().Count==3);});
Test("Snapshot clones isolate mutable coordinates/color/settings",()=>{var b=BoardCodec.Read(fixture);var c=BoardCodec.Clone(b);c.Elements[0].Points[0].X=777;c.Elements[0].Color.R=.9;c.Elements[0].BrushSettings!.MaxWidth=10;Near(b.Elements[0].Points[0].X,12.5);Near(b.Elements[0].Color.R,.16);Near(b.Elements[0].BrushSettings!.MaxWidth,6);});
Test("All ten brush defaults satisfy production validation",()=>{var b=new Board();foreach(var pen in BrushSettings.PenNames){var s=BrushSettings.Defaults(pen);b.Elements.Add(new(){Pen=pen,BrushSettings=s,Width=s.MaxWidth,Points=[new(10,10)]});}Assert(b.Elements.Count==10);BoardCodec.Validate(b);});
Test("Pressure gamma width/opacity and activation endpoints",()=>{var s=new BrushSettings{MinWidth=1,MaxWidth=9,PressureGamma=2,MinOpacity=.2,MaxOpacity=.8,Opacity=.5};Near(s.Width(.5),3);Near(s.Alpha(.5),.175);Near(DrawingMath.CalibratedPressure(.1,.1),0);Near(DrawingMath.CalibratedPressure(.55,.1),.5);Near(DrawingMath.CalibratedPressure(1,.1),1);Near(DrawingMath.CalibratedPressure(-1,.1),0);s.PressureEnabled=false;Near(s.Width(.01),9);});
Test("Pencil tilt and fountain velocity response",()=>{var e=new DrawingElement{Pen="Pencil",BrushSettings=new(){MinWidth=10,MaxWidth=10}};Near(BrushMetrics.Width(e,new(0,0)),10);Near(BrushMetrics.Width(e,new(0,0){TiltX=1}),27);e.Pen="Fountain";Near(BrushMetrics.Width(e,new(0,0){Velocity=2400}),4.5);});
Test("Millimetre scale and exact endpoint independent of display zoom",()=>{var b=new Board{PointsPerMM=4,ScaleDenominator=5};Near(b.Millimetres(80),100);Near(b.DrawingPoints(100),80);var p=DrawingMath.FixedEndpoint(new(5,7),new(8,11),100,b.PointsPerMM,b.ScaleDenominator)!;Near(p.X,53);Near(p.Y,71);Near((p.Point-new Point(5,7)).Length,80);Assert(DrawingMath.FixedEndpoint(new(0,0),new(0,0),10,4,1)==null);Assert(DrawingMath.FixedEndpoint(new(0,0),new(1,0),double.NaN,4,1)==null);});
Test("Held straight line correction keeps measured endpoints",()=>{var e=new DrawingElement{Points=Enumerable.Range(0,30).Select(i=>new InkPoint(i*5,Math.Sin(i)*.5,.2+i/100d)).ToList()};var result=DrawingMath.CorrectShape(e,1);Assert(result.Kind=="line");Assert(e.Kind=="stroke"&&e.Points.Count==30);Near(result.Points[0].Pressure,.2);Near(result.Points[^1].Pressure,.49);});
Test("Held oval and rectangle correction",()=>{var e=new DrawingElement{Points=Enumerable.Range(0,65).Select(i=>new InkPoint(100+Math.Cos(i*Math.PI/32)*70,100+Math.Sin(i*Math.PI/32)*40)).ToList()};Assert(DrawingMath.CorrectShape(e,1).Kind=="ellipse");e.Points=[new(0,0),new(50,0),new(100,0),new(100,50),new(100,100),new(50,100),new(0,100),new(0,50),new(0,0)];Assert(DrawingMath.CorrectShape(e,1).Kind=="rectangle");});
Test("Filled/unfilled shape hit testing",()=>{var e=new DrawingElement{Kind="rectangle",Points=[new(0,0),new(100,100)]};Assert(!DrawingMath.Hit(e,new(50,50),1));Assert(DrawingMath.Hit(e,new(0,50),1));e.Fill=true;Assert(DrawingMath.Hit(e,new(50,50),1));e.Kind="ellipse";Assert(DrawingMath.Hit(e,new(50,50),1));e.Fill=false;Assert(!DrawingMath.Hit(e,new(50,50),1));});
Test("Adaptive smoothing preserves measured pressure objects",()=>{var filter=new AdaptiveInkFilter();var initial=filter.Sample(new(0,0),1,.8,1);var p=filter.Sample(new(10,0),1.01,.8,1);Near(initial.X,0);Assert(p.X>0&&p.X<10);var b=filter.Sample(new(30,0),2,.8,1);Near(b.X,30);});
Test("Validation rejects invalid schema, dimensions and nonfinite coordinates",()=>{var b=new Board{Version=2};Reject(()=>BoardCodec.Validate(b));b=new(){Width=double.NaN};Reject(()=>BoardCodec.Validate(b));b=new(){PointsPerMM=0};Reject(()=>BoardCodec.Validate(b));b=new(){Elements=[new(){Points=[new(double.PositiveInfinity,0)]}]};Reject(()=>BoardCodec.Validate(b));b=new(){Elements=[new(){Points=[new(1000001,0)]}]};Reject(()=>BoardCodec.Validate(b));b=new(){Elements=[new(){Points=[new(0,0,1.01)]}]};Reject(()=>BoardCodec.Validate(b));});
Test("Validation rejects duplicate IDs, malformed colour/settings/3D attachment",()=>{var e=new DrawingElement{Points=[new(0,0)]};var b=new Board{Elements=[e,BoardCodec.Clone(e)]};Reject(()=>BoardCodec.Validate(b));b.Elements=[e];e.Color.A=1.1;Reject(()=>BoardCodec.Validate(b));e.Color.A=1;e.BrushSettings=new(){MinWidth=5,MaxWidth=1};Reject(()=>BoardCodec.Validate(b));e.BrushSettings=null;e.Sketch3D=JsonSerializer.SerializeToElement(new{version=1});Reject(()=>BoardCodec.Validate(b));});
Test("Undo/redo, locked deletion and branching history",()=>{var s=new DrawingSession();s.Commit(new(){Points=[new(0,0)]});s.Commit(new(){Points=[new(50,50)],Locked=true});Assert(s.Board.Elements.Count==2);s.Undo();Assert(s.Board.Elements.Count==1&&s.CanRedo);s.Redo();Assert(s.Board.Elements.Count==2);s.SelectAll();s.DeleteSelection();Assert(s.Board.Elements.Count==1&&s.Board.Elements[0].Locked);s.Undo();Assert(s.Board.Elements.Count==2);s.Commit(new(){Points=[new(7,7)]});Assert(!s.CanRedo);});
Test("Partial eraser cuts a gap even when no sample lies in the gap",()=>{var e=new DrawingElement{Width=2,BrushSettings=new(){MinWidth=2,MaxWidth=2},Points=[new(0,0,.3){RawPressure=.31,TiltX=.2,InputDeviceKey="pen:fixture"},new(100,0,.7){RawPressure=.71,TiltX=.4,InputDeviceKey="pen:fixture"}],Extra=new(){["sourceEvidence"]=JsonSerializer.SerializeToElement("kept")}};var pieces=StrokeEraser.Split(e,new(50,0),10);Assert(pieces.Count==2);Near(pieces[0].Points[^1].X,39);Near(pieces[1].Points[0].X,61);Near(pieces[0].Points[0].RawPressure!.Value,.31);Near(pieces[1].Points[^1].RawPressure!.Value,.71);Near(pieces[0].Points[^1].Pressure,.456);Assert(pieces[0].Points[^1].RawPressure is null);Assert(pieces[0].Points[^1].Extra!["windowsInterpolatedEraseBoundary"].GetBoolean());Assert(pieces.All(p=>p.Extra!["sourceEvidence"].GetString()=="kept"));Assert(e.Points.Count==2&&e.Points[1].X==100);Assert(pieces[0].Id==e.Id&&pieces[1].Id!=e.Id);});
Test("Partial eraser preserves untouched samples and handles miss/full/locked strokes",()=>{var e=new DrawingElement{Width=1,Points=Enumerable.Range(0,11).Select(i=>new InkPoint(i*10,0,.5){RawPressure=.52,TiltY=.3,Velocity=18,InputDeviceKey="pen:real"}).ToList()};Assert(ReferenceEquals(StrokeEraser.Split(e,new(50,50),5)[0],e));var pieces=StrokeEraser.Split(e,new(50,0),8);Assert(pieces.Count==2);Assert(pieces.SelectMany(p=>p.Points).Any(p=>p.X==20&&p.RawPressure==.52&&p.TiltY==.3&&p.Velocity==18&&p.InputDeviceKey=="pen:real"));Assert(StrokeEraser.Split(e,new(50,0),100).Count==0);e.Locked=true;Assert(ReferenceEquals(StrokeEraser.Split(e,new(50,0),100)[0],e));});
Test("Pressure eraser radius and rotated partial stroke preserve world positions",()=>{Near(StrokeEraser.PressureRadius(20,0,1),7);Near(StrokeEraser.PressureRadius(20,1,1),20);var e=new DrawingElement{Width=2,BrushSettings=new(){MinWidth=2,MaxWidth=2},Rotation=90,Points=[new(0,0),new(100,0)]};var parts=StrokeEraser.Split(e,new(50,0),10);Assert(parts.Count==2);Assert(parts.All(p=>p.Rotation==0));Near(parts[0].Points[0].X,50);Near(parts[0].Points[0].Y,-50);Near(parts[1].Points[^1].Y,50);});
Test("Undo and redo share a conservative 64 MiB history estimate",()=>{var board=new Board{Elements=[new(){Points=Enumerable.Range(0,100000).Select(i=>new InkPoint(i%1000,i/1000)).ToList()}]};var session=new DrawingSession();session.SetBoard(board);for(int i=0;i<7;i++){session.Checkpoint();session.Board.Elements[0].Points[0].X=i+.5;session.Board.Title="Step "+i;session.NotifyChanged();}Assert(session.EstimatedHistoryBytes<=DrawingSession.HistoryBudgetBytes);Assert(session.UndoStepCount<7&&session.UndoStepCount>=1);session.Undo();Assert(session.EstimatedHistoryBytes<=DrawingSession.HistoryBudgetBytes&&session.CanRedo);session.Redo();Assert(session.EstimatedHistoryBytes<=DrawingSession.HistoryBudgetBytes);});
Test("Title-only history shares immutable element copies and preserves all steps",()=>{var session=new DrawingSession();session.SetBoard(new(){Elements=[new(){Points=Enumerable.Range(0,100000).Select(i=>new InkPoint(i%1000,i/1000)).ToList()}]});for(int i=0;i<7;i++){session.Checkpoint();session.Board.Title="Title "+i;}Assert(session.UndoStepCount==7);Assert(session.EstimatedHistoryBytes<21L*1024*1024);session.Undo();Assert(session.Board.Title=="Title 5");});
Test("Most recent oversized snapshot remains usable and reports budget exception",()=>{var session=new DrawingSession();session.SetBoard(new(){Elements=[new(){Points=Enumerable.Range(0,340000).Select(i=>new InkPoint(i%1000,i/1000)).ToList()}]});session.Checkpoint();session.Checkpoint();Assert(session.UndoStepCount==1&&session.HistoryBudgetExceeded);session.Board.Title="Changed";session.Undo();Assert(session.Board.Title=="Untitled drawing"&&session.CanRedo);});
Test("History counts shared immutable image/JSON payloads once",()=>{var image=new byte[20*1024*1024];var raw=JsonSerializer.SerializeToElement(new string('r',1024*1024));var session=new DrawingSession();session.SetBoard(new(){Elements=[new(){Kind="image",ImageData=image,Points=[new(0,0),new(100,100)],Extra=new(){["windowsOriginalSamples"]=raw}}]});for(int i=0;i<12;i++){session.Checkpoint();session.Board.Title="Title "+i;}Assert(session.UndoStepCount==12);Assert(session.EstimatedHistoryBytes<24L*1024*1024);});
Test("Shared erase source survives roundtrip and is pruned when no fragment references it",()=>{var source="windowsEraseSource-fixture";var board=new Board{Extra=new(){[source]=JsonSerializer.SerializeToElement(new[]{new InkPoint(0,0,.6){RawPressure=.62}})},Elements=[new(){Points=[new(0,0),new(10,0)],Extra=new(){["windowsEraseSourceKey"]=JsonSerializer.SerializeToElement(source)}}]};var copy=BoardCodec.Deserialize(BoardCodec.Serialize(board));BoardCodec.PruneDerivedMetadata(copy);Assert(copy.Extra!.ContainsKey(source));copy.Elements.Clear();BoardCodec.PruneDerivedMetadata(copy);Assert(!copy.Extra.ContainsKey(source));});
Test("Switching board clears pending symbol intent",()=>{var s=new DrawingSession{PendingSymbolId="symbol-fixture"};s.SetBoard(new());Assert(s.PendingSymbolId==null);});
var temp=Path.Combine(Path.GetTempPath(),"KarimWindowsCore-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
try{
    Test("Atomic save roundtrip leaves no temporary files",()=>{using var store=new BoardStore(temp);store.LoadAsync().GetAwaiter().GetResult();var b=new Board{Title="Atomic fixture"};Assert(store.Save(b));b.Title="Updated";b.Modified+=1;Assert(store.Save(b));Assert(BoardCodec.Read(store.PathFor(b.Id)).Title=="Updated");Assert(!Directory.EnumerateFiles(temp,"*.tmp").Any());});
    Test("Concurrent external edit preserves saved and incoming conflict copies",()=>{using var first=new BoardStore(temp);using var second=new BoardStore(temp);first.LoadAsync().GetAwaiter().GetResult();second.LoadAsync().GetAwaiter().GetResult();var b=first.Boards.First();var other=BoardCodec.Clone(b);other.Title="External writer";other.Modified+=2;Assert(second.Save(other));b.Title="Incoming writer";b.Modified+=3;Assert(!first.Save(b));Assert(first.ConflictingBoardId==b.Id);Assert(BoardCodec.Read(first.PathFor(b.Id)).Title=="External writer");var copies=Directory.EnumerateFiles(Path.Combine(temp,"Archive","Conflicts",b.Id.ToString("D")),"*.engboard").Select(BoardCodec.Read).ToArray();Assert(copies.Any(c=>c.Title=="External writer")&&copies.Any(c=>c.Title=="Incoming writer"));});
    Test("Autosave coalesces and FlushAsync persists latest snapshot",()=>{using var store=new BoardStore(temp);store.LoadAsync().GetAwaiter().GetResult();var b=new Board{Title="First"};store.ScheduleSave(b);b.Title="Second";b.Modified+=1;store.ScheduleSave(b);b.Title="Latest";b.Modified+=1;store.ScheduleSave(b);store.FlushAsync().GetAwaiter().GetResult();Assert(BoardCodec.Read(store.PathFor(b.Id)).Title=="Latest");});
    Test("An older pending autosave cannot overwrite a later explicit save",()=>{using var store=new BoardStore(temp);store.LoadAsync().GetAwaiter().GetResult();var b=new Board{Title="Stale queued"};store.ScheduleSave(b);b.Title="Explicit latest";b.Modified+=1;Assert(store.Save(b));store.FlushAsync().GetAwaiter().GetResult();Assert(BoardCodec.Read(store.PathFor(b.Id)).Title=="Explicit latest");});
    Test("Mac pencil grades and unsupported grade validation",()=>{var b=new Board();foreach(var grade in BrushSettings.PencilGrades)b.Elements.Add(new(){Points=[new(0,0)],BrushSettings=new(){PencilGrade=grade}});BoardCodec.Validate(b);b.Elements[0].BrushSettings!.PencilGrade="3B";Reject(()=>BoardCodec.Validate(b));});
    Test("Corrupt file is reported and kept; valid boards still load",()=>{File.WriteAllText(Path.Combine(temp,"invalid.engboard"),"not json");using var store=new BoardStore(temp);store.LoadAsync().GetAwaiter().GetResult();Assert(store.Error?.Contains("invalid.engboard")==true);Assert(store.Boards.Count>=2);Assert(File.ReadAllText(Path.Combine(temp,"invalid.engboard"))=="not json");});
    Test("Delete archives the exact original file",()=>{using var store=new BoardStore(temp);store.LoadAsync().GetAwaiter().GetResult();var b=store.Boards.First();var content=File.ReadAllBytes(store.PathFor(b.Id));Assert(store.DeleteAsync(b).GetAwaiter().GetResult());Assert(!File.Exists(store.PathFor(b.Id)));var archived=Directory.EnumerateFiles(Path.Combine(temp,"Archive","Deleted"),"*.engboard").First(p=>Path.GetFileName(p).StartsWith(b.Id.ToString()));Assert(File.ReadAllBytes(archived).SequenceEqual(content));});
}finally{Directory.Delete(temp,true);}
var report=new{Scope="Production document/storage/math code on macOS; WPF Point/Rect/Vector/Color test substitutes. No Windows/WPF UI or physical pen test.",Passed=checks.Count,Failed=failures.Count,Checks=checks,Failures=failures,UTC=DateTimeOffset.UtcNow};File.WriteAllText(Path.Combine(Environment.CurrentDirectory,"core-verification-results.json"),JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));return failures.Count==0?0:1;
